import {PlayableSession,playback} from './session.js';
import {geometry,drawCourse,cameraTarget} from './view.js';
import {point} from '../track/oval.js';
import {courseDistance} from '../track/course.js';
import {trackChoices} from '../track/catalog.js';
import {weatherPresets} from '../sim/environment.js';
import {signs} from '../ai/signs.js';
import {coachingProfile,coachingAxes} from '../ai/coaching.js';
import {Commentary} from '../reporting/commentary.js';
import {classification} from '../sim/race.js';
const $=id=>document.getElementById(id),options=[];
for(const kind of ['Oval','Circuit','Rally']){const group=document.createElement('optgroup');group.label=kind;for(const [id,name]of trackChoices(kind)){const option=document.createElement('option');option.value=id.startsWith('generated-')?id.replace('generated-','rally-'):id;option.textContent=name;group.append(option);}options.push(group);}
$('course').replaceChildren(...options);$('weather').replaceChildren(...Object.keys(weatherPresets).map(name=>new Option(name,name)));$('sign').replaceChildren(...signs.map(name=>new Option(name,name)));
for(const axis of coachingAxes){const label=document.createElement('label');label.textContent=axis;const select=document.createElement('select');select.id='coach-'+axis;for(const value of [-1,-.5,0,.5,1])select.append(new Option(String(value),String(value)));select.value='0';label.append(select);$('coachAxes').append(label);}
let session,g,radio,playing=false,debt=0,last=null,lastRender=0,terminal=null,camera=null,comparisonBusy=false,lastDomKey=null;
const measurements={frames:0,mainDrawMs:[],mapDrawMs:[],domMs:[],longTasks:[],inputMs:[],fullRaceWallMs:null};let startedAt=null;
try{new PerformanceObserver(list=>{for(const e of list.getEntries()){measurements.longTasks.push({start:e.startTime,ms:e.duration});if(measurements.longTasks.length>1000)measurements.longTasks.shift();}}).observe({type:'longtask',buffered:true});}catch{}
function record(key,value){measurements[key].push(value);if(measurements[key].length>2000)measurements[key].shift();}
function settings(){return {course:$('course').value,seed:Number($('seed').value),format:$('format').value,weather:$('weather').value,build:$('build').value,value:Number($('value').value),fieldSize:Number($('field').value),laps:Number($('laps').value),...($('customCoach').checked?{coaching:coachingProfile(Object.fromEntries(coachingAxes.map(k=>[k,Number($('coach-'+k).value)])))}:{})};}
function prepare(config=settings()){
 const next=new PlayableSession(config),nextGeometry=geometry(next.state);playing=false;session=next;g=nextGeometry;radio=new Commentary();debt=0;last=null;terminal=null;camera=null;startedAt=null;lastDomKey=null;$('radio').replaceChildren();$('error').textContent='';$('comparison').textContent='';for(const key of ['mainDrawMs','mapDrawMs','domMs','longTasks','inputMs'])measurements[key]=[];measurements.fullRaceWallMs=null;render();
}
function safe(fn){return ()=>{if(comparisonBusy)return;try{fn();}catch(e){playing=false;$('error').textContent=e.message;}render();};}
function input(action){const t=performance.now();if(!session.sign(action,action==='queue'?$('sign').value:undefined))$('error').textContent='Sign rejected by native rules: check format, phase, player condition and remaining opportunities.';else $('error').textContent='';record('inputMs',performance.now()-t);}
function finish(){if(!terminal&&['Ended','Stalled','Error'].includes(session.state.status)){playing=false;terminal=session.official();measurements.fullRaceWallMs=startedAt===null?null:performance.now()-startedAt;}}
function render(){if(!session)return;finish();const s=session.state,p=s.entrants.find(r=>r.id===s.playerId),now=performance.now();
 const actor=cameraTarget(s),target=point(actor.q,actor.lane,s.config,s.track);if(!camera)camera={...target,scale:3};else {camera.x+=(target.x-camera.x)*.35;camera.y+=(target.y-camera.y)*.35;}
 drawCourse($('race'),s,g,{camera});record('mainDrawMs',performance.now()-now);const mapAt=performance.now();drawCourse($('map'),s,g,{map:true});record('mapDrawMs',performance.now()-mapAt);const domAt=performance.now(),domKey=[s.tick,playing,p.signs.remaining,p.signs.active,p.signs.pending,comparisonBusy].join('|');if(lastDomKey===domKey)return;lastDomKey=domKey;
 const open=s.track.course&&!s.track.closed,progress=r=>open?Math.max(0,Math.min(100,courseDistance(r.q,s.track)/s.track.length*100)).toFixed(1)+'%':`lap ${Math.min(s.config.laps,r.completedLaps+1)}/${s.config.laps}`;
 $('status').textContent=terminal?(terminal.cleared?'Official native clearance established. No rewards or career changes.':'Blocked native result: '+terminal.reason):`${playing?'Racing':'Paused / Ready'} · ${s.status} · tick ${s.tick} · ${s.time.toFixed(2)}s · ${session.options.course}`;
 $('hud').textContent=`RU1: ${p.status} · ${progress(p)} · ${p.speed.toFixed(1)} native speed · Driver ${p.ru.driver.condition.toFixed(1)} / strain ${p.ru.driver.strain.toFixed(1)} · Chariot ${p.ru.chariot.condition.toFixed(1)} / wear ${p.ru.chariot.wear.toFixed(1)} · Beasts fatigue ${p.ru.beasts.map(b=>b.fatigue.toFixed(1)).join(' / ')}`;
 $('signState').textContent=`Active: ${p.signs.active??'none'} · Queued: ${p.signs.pending??'none'} · Uses remaining: ${p.signs.remaining}`;
 $('progress').textContent=open?`Sign Points crossed: ${p.checkpointCursor}/${s.track.checkpoints.length} · Next: ${s.track.checkpoints[p.checkpointCursor]?.id??'finish'}`:`${s.format} · ${s.config.laps} laps · Player ${progress(p)}`;
 const official=terminal?.cleared?terminal.classification:null,rows=official??[...s.entrants].sort((a,b)=>(a.finishTime===null)-(b.finishTime===null)||(a.finishTime??0)-(b.finishTime??0)||b.q-a.q||a.id.localeCompare(b.id)).map((r,i)=>({id:r.id,place:i+1,status:r.status,time:r.finishTime}));
 $('standings').replaceChildren(...rows.map(row=>{const tr=document.createElement('tr');if(row.id===s.playerId)tr.className='player';const r=s.entrants.find(r=>r.id===row.id);for(const text of [row.place??'—',row.id,row.status==='Finished'?`${row.time.toFixed(3)}s`:row.status==='Racing'?progress(r):row.status]){const td=document.createElement('td');td.textContent=text;tr.append(td);}return tr;}));
 $('clearance').textContent=terminal?(terminal.cleared?'Official placement uses native full precision and tie tolerance.':'Uncleared: no official result. Restart or inspect diagnostics.'):'Live order is provisional.';
 const n=radio.lines.length;radio.consume(s.events);const added=radio.lines.slice(n);for(const line of added){const div=document.createElement('div');div.textContent=`${line.time.toFixed(2)} · ${line.text}`;$('radio').append(div);}while($('radio').children.length>160)$('radio').firstChild.remove();radio.lines=radio.lines.slice(-200);if(added.length)$('radio').scrollTop=$('radio').scrollHeight;
 for(const option of $('sign').options)option.disabled=option.value==='Engage Rivals'&&s.format==='Pure';if($('sign').selectedOptions[0]?.disabled)$('sign').value=signs[0];
 const stopped=['Ended','Stalled','Error'].includes(s.status);$('queue').disabled=comparisonBusy||stopped||p.signs.remaining===0||p.status!=='Racing';$('cancel').disabled=comparisonBusy||stopped||!p.signs.pending;$('lower').disabled=comparisonBusy||stopped||!p.signs.active;for(const id of ['start','step'])$(id).disabled=comparisonBusy||stopped;$('pause').disabled=comparisonBusy||!playing;
 $('diagnostics').textContent=JSON.stringify({prototype:'p1-playable-v1',presetChanges:session.changes,coaching:session.state.entrants[0].coachingContext??null,simulationVersion:s.version,seed:s.seed,tick:s.tick,events:s.events.length,maxTickMs:session.maxTickMs,rollingTickSamples:session.timings.length,geometrySamples:g.samples,clearance:terminal?.cleared??false},null,2);
 record('domMs',performance.now()-domAt);measurements.frames++;
}
$('prepare').onclick=safe(()=>prepare());$('restart').onclick=safe(()=>prepare(session.options));$('start').onclick=safe(()=>{playing=true;last=null;startedAt??=performance.now();});$('pause').onclick=safe(()=>{playing=false;last=null;});$('step').onclick=safe(()=>{playing=false;startedAt??=performance.now();session.tick();});for(const [id,action]of [['queue','queue'],['cancel','cancel'],['lower','lower']])$(id).onclick=safe(()=>input(action));
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=safe(()=>download({...session.metrics(),setup:session.setup,changes:session.changes,performance:measurements},'BNT-P1-race-metrics.json'));
async function compare(){if(comparisonBusy)return;playing=false;comparisonBusy=true;for(const b of document.querySelectorAll('button,input,select'))b.disabled=true;const output=[];try{const config=settings();delete config.coaching;const rivals=[];for(const build of ['contact','handling']){const test=new PlayableSession({...config,build});rivals.push(JSON.stringify(test.setup.entrants.slice(1)));while(!['Ended','Stalled','Error'].includes(test.state.status)&&test.state.tick<20000){const start=performance.now();do{test.tick();}while(!['Ended','Stalled','Error'].includes(test.state.status)&&test.state.tick<20000&&performance.now()-start<8);$('comparison').textContent=`Running ${build} · tick ${test.state.tick}. No Strategy Sign inputs; controls locked during comparison.`;await new Promise(r=>setTimeout(r,0));}output.push(test.metrics());}if(rivals[0]!==rivals[1])throw Error('Comparison rival configuration mismatch');window.P1.lastComparison=output;$('comparison').replaceChildren();for(const m of output){const pre=document.createElement('pre');pre.textContent=JSON.stringify({build:m.build,status:m.status,cleared:m.clearance.cleared,checksum:m.checksum,player:m.player},null,2);$('comparison').append(pre);}}catch(e){$('error').textContent=e.message;}finally{comparisonBusy=false;for(const b of document.querySelectorAll('button,input,select'))b.disabled=false;lastDomKey=null;render();}}
$('compare').onclick=compare;
function frame(now){try{if(playing&&!comparisonBusy){if(last!==null){const r=playback(session,debt,(now-last)/1000,Number($('speed').value));debt=r.accumulator;}last=now;finish();}if((playing||now-lastRender>200)&&!comparisonBusy){render();lastRender=now;}}catch(e){playing=false;$('error').textContent=e.message;}requestAnimationFrame(frame);}
window.P1={version:'p1-playable-v1',get session(){return session;},get measurements(){return measurements;},prepare,compare,classification,draw:render,lastComparison:null};prepare();requestAnimationFrame(frame);
